proof fn always_double_equality<T>(p: TempPred<T>)
    ensures always(always(p)) == always(p),
{
    // Entailment for TempPred is extensional: p.entails(q) <==> forall ex, p.satisfied_by(ex) ==> q.satisfied_by(ex).
    // We prove both directions by unfolding `always`.

    assert(always(always(p)).entails(always(p))) by {
        assert(forall |ex: Execution<T>| #[trigger]
            always(always(p)).satisfied_by(ex) ==> always(p).satisfied_by(ex)
        ) by {
            if always(always(p)).satisfied_by(ex) {
                // Need: forall k, p.satisfied_by(ex.suffix(k))
                assert(forall |k: nat| #[trigger] p.satisfied_by(ex.suffix(k))) by {
                    // from always(always(p)) we get always(p) at ex.suffix(0)
                    assert(always(p).satisfied_by(ex.suffix(0)));
                    // and thus p at ex.suffix(0).suffix(k)
                    assert(p.satisfied_by(ex.suffix(0).suffix(k)));
