proof fn suffix_compose<T>(ex: Execution<T>, i: nat, j: nat)
    ensures ex.suffix(i).suffix(j) == ex.suffix(i + j),
{
    assert(forall |t: nat| #[trigger]
        (ex.suffix(i).suffix(j).nat_to_state)(t) == (ex.suffix(i + j).nat_to_state)(t)
    );
    execution_equality(ex.suffix(i).suffix(j), ex.suffix(i + j));
}

// Helper lemma: suffix by 0 is the identity
proof fn suffix_zero<T>(ex: Execution<T>)
    ensures ex.suffix(0) == ex,
{
    assert(forall |t: nat| #[trigger]
        (ex.suffix(0).nat_to_state)(t) == (ex.nat_to_state)(t)
    );
    execution_equality(ex.suffix(0), ex);
}

proof fn always_double_equality<T>(p: TempPred<T>)
    ensures always(always(p)) == always(p),
{
    // 1) always(always(p)).entails(always(p))
    assert(always(always(p)).entails(always(p))) by {
        assert(forall |ex: Execution<T>| #[trigger]
            always(always(p)).satisfied_by(ex) ==> always(p).satisfied_by(ex)
        ) by {
            if always(always(p)).satisfied_by(ex) {
                assert(forall |k: nat| #[trigger] p.satisfied_by(ex.suffix(k))) by {
                    // From the outer always with i = 0
                    assert(always(p).satisfied_by(ex.suffix(0)));
                    assert(p.satisfied_by(ex.suffix(0).suffix(k)));
                    suffix_compose(ex, 0, k);
                    assert(p.satisfied_by(ex.suffix(k)));
                };
            }
        };
    };

    // 2) always(p).entails(always(always(p)))
    assert(always(p).entails(always(always(p)))) by {
        assert(forall |ex: Execution<T>| #[trigger]
            always(p).satisfied_by(ex) ==> always(always(p)).satisfied_by(ex)
        ) by {
            if always(p).satisfied_by(ex) {
                assert(forall |i: nat| #[trigger] always(p).satisfied_by(ex.suffix(i))) by {
                    assert(forall |j: nat| #[trigger] p.satisfied_by(ex.suffix(i).suffix(j))) by {
                        // Use the original always(p) at index i + j
                        assert(p.satisfied_by(ex.suffix(i + j)));
                        suffix_compose(ex, i, j);
                        assert(p.satisfied_by(ex.suffix(i).suffix(j)));
                    };
                };
            }
        };
    };

    temp_pred_equality(always(always(p)), always(p));
}
